import{_ as o,C as s,c as n,o as r,a3 as e,G as i}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Balance sheet","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/reporting/balance-sheet.md","filePath":"master/finance/reporting/balance-sheet.md","lastUpdated":1791902625000}'),l={name:"master/finance/reporting/balance-sheet.md"};function h(d,t,c,u,p,g){const a=s("ImagePopup");return r(),n("div",null,[t[0]||(t[0]=e('<h1 id="balance-sheet" tabindex="-1">Balance sheet <a class="header-anchor" href="#balance-sheet" aria-label="Permalink to &quot;Balance sheet&quot;">​</a></h1><p>The balance sheet shows what your company owns (assets), what it owes (liabilities) and what is left for the owners (equity) on one date. Use it at month end, or when a bank or an investor asks for your financial position.</p><blockquote><p><strong>In simple words:</strong> The balance sheet is a photo of your money on one day. Assets on one side, debts and equity on the other.</p></blockquote><p>It is in the Accounting app only: <code>Accounting → Reporting → Balance Sheet</code>.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2>',5)),i(a,{src:"/images1/finance/balance_sheet.png",alt:"Balance Sheet with Date Range Last Quarter (01/07/2026 - 30/09/2026), showing Assets, Liabilities and Equity sections"}),t[1]||(t[1]=e('<ul><li><strong><em>Date Range:</em></strong> The report is &quot;as of&quot; the last day of the range. It adds up everything posted up to that date, not only inside the range. The title reads <strong>Balance Sheet - As of</strong> with the date.</li><li><strong><em>Journals:</em></strong> Limit the report to chosen journals.</li></ul><h2 id="how-to-read-it" tabindex="-1">How to read it <a class="header-anchor" href="#how-to-read-it" aria-label="Permalink to &quot;How to read it&quot;">​</a></h2><p>The report has two columns: <strong>Account</strong> and <strong>Balance</strong>. It has three blocks.</p><h3 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h3><ul><li><strong>Current Assets:</strong> Cash, receivables and similar.</li><li><strong>Fixed Assets</strong> and <strong>Non-current Assets:</strong> Long term items. They are empty in the sample data.</li></ul><p>Example, as of Oct 31, 2026:</p><table tabindex="0"><thead><tr><th>Account</th><th>Balance</th></tr></thead><tbody><tr><td>101403 - Outstanding Receipts</td><td>891.25</td></tr><tr><td>101404 - Outstanding Payments</td><td>-34,040.00</td></tr><tr><td>121000 - Account Receivable</td><td>1,207.50</td></tr><tr><td>131000 - Tax Paid</td><td>4,440.00</td></tr><tr><td>Total Current Assets</td><td>-27,501.25</td></tr></tbody></table><p>Account Receivable of $1,207.50 is invoice INV/2026/1, still unpaid.</p><h3 id="liabilities" tabindex="-1">Liabilities <a class="header-anchor" href="#liabilities" aria-label="Permalink to &quot;Liabilities&quot;">​</a></h3><ul><li><strong>Current Liabilities:</strong> <strong>211000 - Account Payable</strong> (0.00, the bill is paid) and <strong>251000 - Tax Received</strong> (273.75).</li><li><strong>Non-current Liabilities:</strong> Long term debts.</li></ul><p><strong>Total LIABILITIES</strong> is 273.75.</p><h3 id="equity" tabindex="-1">Equity <a class="header-anchor" href="#equity" aria-label="Permalink to &quot;Equity&quot;">​</a></h3><ul><li><strong>Unallocated Earnings</strong> holds profit that is not moved to an equity account yet.</li><li><strong>Current Year Unallocated Earnings:</strong> -27,775.00. It is the net profit of the year to date. See <a href="./profit-and-loss.html">Profit and loss</a>.</li><li><strong>Previous Years Unallocated Earnings:</strong> 0.00.</li></ul><p><strong>Total EQUITY</strong> is shown as 27,775.00 and <strong>LIABILITIES + EQUITY</strong> as 28,048.75.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>In this sample the numbers are odd because the data has only one vendor payment and a large bill. A real company starts with opening balances and has positive equity.</p></div><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Click <strong>Export to Excel</strong> or <strong>Export to PDF</strong> at the top right. The file uses the same date and filters.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Why is the report empty?</strong> The default range is the current month. Pick a range up to a date with posted entries.</p><p><strong>Why do my draft invoices not show?</strong> Only posted entries count. Confirm the invoice first.</p><p><strong>Why is Current Year Unallocated Earnings a minus number?</strong> Your expenses are larger than your revenue so far. The result is a loss.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./profit-and-loss.html">Profit and loss</a></li><li><a href="./trial-balance.html">Trial balance</a></li><li><a href="./../get-started/chart-of-accounts.html">Chart of accounts</a></li></ul>',23))])}const f=o(l,[["render",h]]);export{b as __pageData,f as default};
